import {Battle} from './engine.js';import {createSave} from './model.js';import {renderBattle} from './art.js';import {SMALL_POOLS,SMALL_SPECIES,SMALL_MOVES,SMALL_TIMING,createSmall,beginSmallAttack} from './small-monsters.js';import {drawSmall} from './small-art.js';
const $=id=>document.getElementById(id);let b,last=0;
function reset(){b=new Battle(createSave('观察员','female'),Number($('area').value));b.m.x=1720;b.m.state='recover';b.m.timer=10000;}
function sheets(){const kind=$('species').value;$('sheets').innerHTML='';for(let move=0;move<3;move++){const section=document.createElement('section'),h=document.createElement('h2'),canvas=document.createElement('canvas');h.textContent=SMALL_MOVES[SMALL_SPECIES[kind].moves[move]].name;canvas.width=1000;canvas.height=180;section.append(h,canvas);$('sheets').append(section);const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;[['windup',.95],['strike',.55],['recover',.3],['recover',.95]].forEach(([state,u],i)=>{const s=createSmall(kind,0,()=>0);beginSmallAttack(s,move,100);s.state=state;s.age=SMALL_TIMING[state]*u;s.x=0;s.y=0;c.save();c.translate(110+i*235,125);c.scale(1.6,1.6);drawSmall(c,s,0);c.restore();c.fillStyle='#526a59';c.font='14px system-ui';c.textAlign='center';c.fillText(['蓄势','攻击','收招','恢复'][i],110+i*235,163);});}}
function area(){reset();$('species').innerHTML='';for(const id of SMALL_POOLS[Number($('area').value)]){const o=document.createElement('option');o.value=id;o.textContent=SMALL_SPECIES[id].name+(SMALL_SPECIES[id].fly?' · 飞行':' · 陆地');$('species').append(o);}sheets();}
$('area').onchange=area;$('species').onchange=sheets;$('reroll').onclick=reset;
for(const [id,fly] of [['land',false],['air',true]])$(id).onclick=()=>{const s=b.smalls.find(s=>!!s.fly===fly&&s.hp>0);if(s){b.p.x=s.x-65;b.p.face=1;b.p.y=0;b.p.vy=0;}};
$('away').onclick=()=>{b.p.x=120;b.p.y=0;b.p.vy=0;};for(const kind of ['attack','jump','dodge'])$(kind).onclick=()=>b.act(kind);
const states={idle:'游荡',windup:'蓄势',strike:'攻击',recover:'收招',dead:'已击败'};
function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;b.step(dt);renderBattle($('battle'),b);$('status').textContent=`猎人生命 ${b.p.hp}/${b.p.maxHp} · 本次 ${b.smalls.length} 种：`+b.smalls.map(s=>`${s.name} ${s.hp}/${s.maxHp} ${states[s.state]}`).join(' / ');requestAnimationFrame(frame);}area();requestAnimationFrame(frame);
